  let output = `
🎯 Claude Design Conformance Scorecard (Phase 1 — 10 Automated Checks)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
File: ${fileRef}
Verdict: ${verdict}
Score: ${total}/20 (${percentage.toFixed(0)}%)

| Criterion | Category | Score | Notes |
|---|---|---|---|
`;
